<template><div class="page"><h1>经营资料汇总</h1><p>汇总有权查看的销售、财务、售后和库存资料，供人工核对。</p><el-alert title="销售和财务口径不同，不可直接相加；客服、团队及跨平台数据尚未接入。" type="info" :closable="false"/><el-form class="section" inline @submit.prevent="load"><el-select v-model="days" @change="load" style="width:200px"><el-option :value="7" label="近7个完整自然日"/><el-option :value="30" label="近30个完整自然日"/></el-select><el-button :loading="loading" @click="load">刷新资料</el-button></el-form><el-card class="section"><template #header>智能体经营汇总</template><p>基于当前授权资料整理，结果供人工核对。</p><el-select v-model="topic" style="width:220px;margin-right:12px" :disabled="analysisLoading" @change="clearAnalysis"><el-option value="auto" label="按问题智能分配（调用模型）" :disabled="!canSales && !canFinance && !canRisk && !canInventory"/><el-option value="both" label="全部授权资料"/><el-option value="sales" label="销售资料" :disabled="!canSales"/><el-option value="finance" label="财务资料" :disabled="!canFinance"/><el-option value="risk" label="售后资料" :disabled="!canRisk"/><el-option value="inventory" label="库存资料" :disabled="!canInventory"/></el-select><el-button :loading="analysisLoading" :disabled="(!canSales && !canFinance && !canRisk && !canInventory) || (topic==='auto' && !question.trim())" @click="analyze">生成汇总</el-button><p v-if="topic === 'auto'">智能分配会将问题发送给模型服务并可能产生费用；支持销售、财务、售后及当前库存汇总；不支持历史库存。</p><p><el-checkbox v-model="useModel" :disabled="analysisLoading" @change="clearAnalysis">同时生成模型解读（可能产生费用，问题及汇总资料将发送给模型服务）</el-checkbox></p><el-input v-if="useModel || topic === 'auto'" v-model="question" type="textarea" maxlength="500" show-word-limit :placeholder="topic === 'auto' ? '请输入要查询的问题，请勿输入敏感个人信息' : '可填写希望解读的问题，请勿输入敏感个人信息'" :disabled="analysisLoading" @input="clearAnalysis"/><p v-if="analysisError">汇总生成失败，请根据提示调整问题或重试。</p><template v-if="analysis"><p v-if="analysis.modelStatus === 'disabled'">模型未启用，仅显示规则汇总。</p><p v-else-if="analysis.modelStatus === 'unavailable'">模型暂不可用，仅显示规则汇总。</p><div v-else-if="analysis.explanation"><h3>模型解读（须人工核实）</h3><p style="white-space:pre-wrap">{{ analysis.explanation }}</p></div><p>{{ analysis.scope }} · 近 {{ analysis.days }} 个完整自然日</p><p v-if="analysis.days !== days">智能分配采用了不同周期，请核对；下方销售和财务资料仍按页面选择的周期显示。</p><div v-for="item in analysis.sections" :key="item.source"><p>{{ item.summary }}</p><p>{{ item.limitation }}</p></div></template></el-card><div class="grid"><el-card><template #header>销售与订单</template><p v-if="!canSales">无销售资料权限</p><div v-else-if="salesError"><p>销售资料加载失败，不能视为零。</p><el-button :loading="salesLoading" @click="retrySales">重试销售资料</el-button></div><p v-else-if="!sales">正在加载…</p><template v-else><p>{{ sales.scope }} · {{ sales.start }} 至 {{ sales.endExclusive }}（不含结束时间）</p><p>全部订单 {{ sales.current.orders }} 笔，有效支付订单 {{ sales.current.paidOrders }} 笔；支付金额 {{ sales.current.payment }}。</p><p>{{ sales.limitation }}</p><router-link to="/sales-agent">查看销售资料详情</router-link></template></el-card><el-card><template #header>财务资料</template><p v-if="!canFinance">无财务资料权限</p><div v-else-if="financeError"><p>财务资料加载失败，不能视为零。</p><el-button :loading="financeLoading" @click="retryFinance">重试财务资料</el-button></div><p v-else-if="!finance">正在加载…</p><template v-else><p>{{ finance.scope }} · {{ finance.start }} 至 {{ finance.endExclusive }}（不含结束时间）</p><p>原单支付 {{ finance.orders.payment }}；匹配已完成退款 {{ finance.refunds.amount }}；差额 {{ finance.paymentLessRefund }}。</p><p>利润暂不可可靠计算。{{ finance.limitation }}</p><router-link to="/finance-agent">查看财务资料详情</router-link></template></el-card><el-card v-if="canFinance"><template #header>多店对比</template><div v-if="shopError"><p>多店对比资料加载失败，不能视为零。</p><el-button :loading="shopLoading" @click="retryShop">重试多店对比</el-button></div><p v-else-if="!shopComparison">正在加载…</p><template v-else><el-table :data="shopComparison.shops" empty-text="当前范围及窗口没有符合支付口径的订单"><el-table-column label="店铺 ID" min-width="110"><template #default="scope">{{ scope.row.shopId ?? '归属缺失，待核实' }}</template></el-table-column><el-table-column prop="orders" label="订单数" /><el-table-column prop="payment" label="支付额" /><el-table-column prop="refundAmount" label="退款金额" /><el-table-column prop="settledOrders" label="已结算单数" /><el-table-column label="结算销售额"><template #default="scope">{{ scope.row.settledSalesAmount === null ? '无已审核结算单' : scope.row.settledSalesAmount }}</template></el-table-column><el-table-column label="结算利润"><template #default="scope">{{ scope.row.profit === null ? '无已审核结算单' : scope.row.profit }}</template></el-table-column></el-table><p class="muted">{{ shopComparison.limitation }}</p></template></el-card></div></div></template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useUserStore} from '@/store/modules/user'
import {getSalesOverview} from '@/api/ai/salesAgent'
import type {SalesOverview} from '@/api/ai/salesAgent'
import {getFinanceOverview,getShopComparison} from '@/api/ai/financeAgent'
import type {FinanceOverview,ShopComparisonResult} from '@/api/ai/financeAgent'
import request from '@/utils/request'
const user=useUserStore(),days=ref(30),loading=ref(false),sales=ref<SalesOverview|null>(null),finance=ref<FinanceOverview|null>(null),salesError=ref(false),financeError=ref(false)
const shopComparison=ref<ShopComparisonResult|null>(null),shopError=ref(false),shopLoading=ref(false)
const canSales=computed(()=>user.permissions.some(p=>p==='*:*:*'||p==='ai:sales:query')),canFinance=computed(()=>user.permissions.some(p=>p==='*:*:*'||p==='ai:finance:query')),canRisk=computed(()=>user.permissions.some(p=>p==='*:*:*'||p==='ai:risk:query')),canInventory=computed(()=>user.permissions.some(p=>p==='*:*:*'||p==='ai:inventory:query'))
interface ManagementAnalysis { days:number; scope:string; modelStatus:string; explanation:string|null; sections:{source:string;summary:string;limitation:string}[] }
const topic=ref('both'),useModel=ref(false),question=ref(''),analysis=ref<ManagementAnalysis|null>(null),analysisLoading=ref(false),analysisError=ref(false)
let analysisSequence=0
function clearAnalysis(){analysisSequence++;analysis.value=null;analysisError.value=false;analysisLoading.value=false}
async function analyze(){const id=++analysisSequence;analysis.value=null;analysisError.value=false;analysisLoading.value=true;try{const r=await request<any,{data:ManagementAnalysis}>({url:'/api/erp-api/ai-agent/management/analysis',method:'post',params:{days:days.value,topic:topic.value},data:{question:useModel.value||topic.value==='auto'?question.value:'',useModel:useModel.value},timeout:65000});if(id===analysisSequence)analysis.value=r.data}catch{if(id===analysisSequence)analysisError.value=true}finally{if(id===analysisSequence)analysisLoading.value=false}}
let sequence=0
const salesLoading=ref(false),financeLoading=ref(false)
async function retrySales(){const id=sequence;salesLoading.value=true;try{const r=await getSalesOverview(days.value);if(id===sequence){sales.value=r.data;salesError.value=false}}catch{if(id===sequence)salesError.value=true}finally{if(id===sequence)salesLoading.value=false}}
async function retryFinance(){const id=sequence;financeLoading.value=true;try{const r=await getFinanceOverview(days.value);if(id===sequence){finance.value=r.data;financeError.value=false}}catch{if(id===sequence)financeError.value=true}finally{if(id===sequence)financeLoading.value=false}}
async function retryShop(){const id=sequence;shopLoading.value=true;try{const r=await getShopComparison(days.value);if(id===sequence){shopComparison.value=r.data;shopError.value=false}}catch{if(id===sequence)shopError.value=true}finally{if(id===sequence)shopLoading.value=false}}
async function load(){clearAnalysis();const id=++sequence;loading.value=true;sales.value=null;finance.value=null;shopComparison.value=null;salesError.value=false;financeError.value=false;shopError.value=false;salesLoading.value=false;financeLoading.value=false;shopLoading.value=false;await Promise.all([canSales.value?retrySales():Promise.resolve(),canFinance.value?retryFinance():Promise.resolve(),canFinance.value?retryShop():Promise.resolve()]);if(id===sequence)loading.value=false}
onMounted(()=>void load())
</script>
<style scoped>.page{max-width:1300px;margin:auto;padding:24px;color:#263344}.section{margin-top:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px}.grid p{line-height:1.7}.muted{color:#738096;font-size:13px}</style>
